init.source:
static const float METRES_PER_UNIT = 0.01;
static const float GRAVITY = 981;
static const float CAPILLARY = 72.8;
static const float DOMAIN = 0.8;
static const float MARKER_SPACING = 0.015;
static const float KERNEL_SUPPORT = 0.0403846153846;
static const float CONTACT_OFFSET = 0.00576923076923;
static const float FLIP_BLEND = 0;
static const float FILM_DIFFUSIVITY = 0;
static const float3 DOMAIN_EXTENT = float3(0.8,0.8,0.8);
static const float3 DOMAIN_ORIGIN = float3(0.0,0.3,0.0);
static const uint3 BIN_DIMS = uint3(32,32,32);
static const uint BIN_RES = 32u;
#include "fluid/config.slang"

float container(float3 p) {
    return max(max(abs(p.x)-0.70,abs(p.z)-0.70),-0.13-p.y);
}
float initial_field(float3 p) {
    float pool=max(max(abs(p.x)-0.66,abs(p.z)-0.66),max(p.y,-0.125-p.y));
    float drop=length(p-float3(0,0.45,0))-0.275;
    return max(min(pool,drop),container(p));
}
bool initial_marker(uint id,out float3 p) {
    // Bounded pool lattice: 88 x 8 x 88. Extra 38^3 slots seed the drop.
    if(id<61952u) {
        uint ix=id%88u; uint iy=(id/88u)%8u; uint iz=id/(88u*8u);
        p=float3(-0.6525+0.015*ix,-0.1125+0.015*iy,-0.6525+0.015*iz);
        return initial_field(p)<0 && container(p)<0;
    }
    uint q=id-61952u;
    uint ix=q%38u; uint iy=(q/38u)%38u; uint iz=q/(38u*38u);
    p=float3(-0.2775+0.015*ix,0.1725+0.015*iy,-0.2775+0.015*iz);
    return length(p-float3(0,0.45,0))<0.275 && container(p)<0;
}
float3 initial_velocity(float3 cellCentre,float dx) {
    // Only the drop has downward speed; Y is sampled at its negative MAC face.
    float3 yface=cellCentre-float3(0,0.5*dx,0);
    return float3(0,length(yface-float3(0,0.45,0))<0.275 ? -70.0 : 0.0,0);
}
float initial_pressure(float3 p) { return 0; }
bool film_accept(float2 xz) { return false; }
float film_height(float2 xz) { return -0.13; }
float3 boundary_velocity(float3 p,float time,float3 v) { return v; }

struct Inputs {int stage=0;};
#include "fluid/solver.slang"

